  "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Edit profile</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&family=Source+Sans+3:wght@300..900&family=JetBrains+Mono:wght@400;500;600&display=swap"
      rel="stylesheet"
    />
    <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/tokens.css" />
    <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/base.css" />
    <script type="module" src="./node_modules/@taproot-ds/web-components/src/index.js"></script>
    <style>
      main {
        max-width: 32rem;
        margin: 0 auto;
        padding: var(--ds-primitives-space-12) var(--ds-primitives-space-6);
      }
      h1 {
        margin: 0 0 var(--ds-primitives-space-6);
      }
      form {
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-6);
      }
      .form-actions {
        display: flex;
        justify-content: flex-start;
      }
    </style>
  </head>
  <body>
    <main>
      <h1>Edit profile</h1>
      <form id="profile-form" novalidate>
        <ds-alert variant="danger" label="Changes not saved">
          The connection dropped before your changes reached us. Check your connection and try again.
          <ds-button slot="actions" type="submit" variant="secondary" size="small">Try again</ds-button>
        </ds-alert>

        <ds-text-field
          label="Name"
          name="name"
          autocomplete="name"
          value="Sam Rivera"
          required
        ></ds-text-field>

        <ds-text-field
          label="Email"
          name="email"
          type="email"
          autocomplete="email"
          value="sam@"
          error="Enter the rest of your email address after the @, like sam@example.com"
          required
        ></ds-text-field>

        <div class="form-actions">
          <ds-button type="submit" variant="primary">Save changes</ds-button>
        </div>
      </form>
    </main>
    <script type="module">
      const form = document.getElementById("profile-form");
      for (const field of form.querySelectorAll("ds-text-field")) {
        field.addEventListener("input", () => field.removeAttribute("error"));
      }
      form.addEventListener("reset", () => {
        for (const field of form.querySelectorAll("ds-text-field")) field.removeAttribute("error");
      });
      form.addEventListener("submit", (event) => event.preventDefault());
    </script>
  </body>
</html>
